CREATE TABLE public.economy_config (key text PRIMARY KEY, value jsonb NOT NULL, description text NOT NULL DEFAULT '');
GRANT SELECT ON public.economy_config TO authenticated; GRANT ALL ON public.economy_config TO service_role; ALTER TABLE public.economy_config ENABLE ROW LEVEL SECURITY; CREATE POLICY "Players read economy" ON public.economy_config FOR SELECT TO authenticated USING (true);
ALTER TABLE public.aircraft_types ADD COLUMN fuel_type text NOT NULL DEFAULT '100LL', ADD COLUMN fuel_burn_gph numeric NOT NULL DEFAULT 9, ADD COLUMN fuel_capacity_gal numeric NOT NULL DEFAULT 56, ADD COLUMN minimum_runway_ft integer NOT NULL DEFAULT 1500, ADD COLUMN active boolean NOT NULL DEFAULT true;
UPDATE public.aircraft_types SET fuel_type='Jet-A',fuel_burn_gph=110,fuel_capacity_gal=539,minimum_runway_ft=3300 WHERE id='B350'; UPDATE public.aircraft_types SET fuel_burn_gph=28,fuel_capacity_gal=194,minimum_runway_ft=2300 WHERE id='BE58';
ALTER TABLE public.airports ADD COLUMN size integer NOT NULL DEFAULT 3 CHECK(size BETWEEN 1 AND 7), ADD COLUMN development_level integer NOT NULL DEFAULT 1, ADD COLUMN airport_type text NOT NULL DEFAULT 'unknown', ADD COLUMN elevation_ft integer, ADD COLUMN longest_runway_ft integer, ADD COLUMN runway_surface text, ADD COLUMN fuel_100ll_available boolean, ADD COLUMN fuel_jeta_available boolean, ADD COLUMN data_source text NOT NULL DEFAULT 'starter', ADD COLUMN classification_source text NOT NULL DEFAULT 'provisional';
CREATE TABLE public.airport_passenger_pools (airport_icao text PRIMARY KEY REFERENCES public.airports(icao), stock numeric NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), last_departure_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.airport_passenger_pools TO authenticated; GRANT ALL ON public.airport_passenger_pools TO service_role; ALTER TABLE public.airport_passenger_pools ENABLE ROW LEVEL SECURITY; CREATE POLICY "Players read passenger pools" ON public.airport_passenger_pools FOR SELECT TO authenticated USING (true);
CREATE TABLE public.flights (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), aircraft_id uuid NOT NULL REFERENCES public.fleet_aircraft(id), origin_icao text NOT NULL REFERENCES public.airports(icao), destination_icao text NOT NULL REFERENCES public.airports(icao), status text NOT NULL DEFAULT 'DISPATCHED' CHECK(status IN ('DISPATCHED','EN_ROUTE','COMPLETED','CANCELLED')), execution_source text NOT NULL DEFAULT 'WEB_MANUAL' CHECK(execution_source IN ('WEB_MANUAL','ACARS_AGENT')), passengers integer NOT NULL, distance_nm numeric NOT NULL, estimated_minutes numeric NOT NULL, estimate jsonb NOT NULL, rules_snapshot jsonb NOT NULL, departed_at timestamptz, completed_at timestamptz, telemetry jsonb, settlement jsonb, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.flights TO authenticated; GRANT ALL ON public.flights TO service_role; ALTER TABLE public.flights ENABLE ROW LEVEL SECURITY; CREATE POLICY "Owners read flights" ON public.flights FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.companies c WHERE c.id=company_id AND c.user_id=auth.uid())); CREATE UNIQUE INDEX one_active_flight_per_aircraft ON public.flights(aircraft_id) WHERE status IN ('DISPATCHED','EN_ROUTE'); CREATE INDEX flights_company_created ON public.flights(company_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.economy_number(p_key text) RETURNS numeric LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v numeric; BEGIN SELECT (value #>> '{}')::numeric INTO v FROM economy_config WHERE key=p_key; IF v IS NULL OR v<0 THEN RAISE EXCEPTION 'Missing or invalid economy rule: %',p_key; END IF; RETURN v; END $$; REVOKE ALL ON FUNCTION public.economy_number(text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.passenger_capacity(p_airport text) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (e.value->>(a.size-1))::numeric*(1+0.1*(greatest(a.development_level,1)-1)) FROM airports a CROSS JOIN economy_config e WHERE a.icao=p_airport AND e.key='airport_capacities' $$;
CREATE OR REPLACE FUNCTION public.passenger_stock(p_airport text) RETURNS numeric LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p airport_passenger_pools%ROWTYPE; cap numeric:=passenger_capacity(p_airport); ceiling numeric:=cap*economy_number('natural_cap'); hours numeric; burnout numeric; BEGIN SELECT * INTO p FROM airport_passenger_pools WHERE airport_icao=p_airport; IF NOT FOUND THEN RETURN cap*economy_number('initial_stock'); END IF; hours:=greatest(0,extract(epoch FROM now()-p.updated_at)/3600); burnout:=greatest(0,extract(epoch FROM now()-greatest(p.updated_at,p.last_departure_at+make_interval(hours=>economy_number('burnout_idle_hours')::integer)))/3600); IF p.stock<ceiling THEN RETURN least(ceiling,p.stock+cap*economy_number('hourly_rate')*hours); END IF; RETURN least(cap*economy_number('transit_cap'),greatest(ceiling,p.stock-cap*economy_number('hourly_rate')*burnout)); END $$; REVOKE ALL ON FUNCTION public.passenger_capacity(text),public.passenger_stock(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.passenger_capacity(text),public.passenger_stock(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.create_company(p_name text,p_icao_code text,p_home_base text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); cid uuid; code text:=upper(trim(p_icao_code)); capital numeric:=economy_number('starting_capital'); BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; IF length(trim(p_name))<3 OR length(trim(p_name))>60 THEN RAISE EXCEPTION 'Airline name must contain 3–60 characters'; END IF; IF code !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'ICAO code must be exactly 3 letters'; END IF; INSERT INTO companies(user_id,name,icao_code,home_base_icao) VALUES(uid,trim(p_name),code,upper(p_home_base)) RETURNING id INTO cid; INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,idempotency_key) VALUES(cid,'INITIAL_GRANT','COMPANY_CASH','SYSTEM_TREASURY',capital,capital,capital,'Initial Smooth Coins grant','initial_grant:'||cid); RETURN cid; END $$;
CREATE OR REPLACE FUNCTION public.lease_aircraft(p_type text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c companies%ROWTYPE; t aircraft_types%ROWTYPE; bal numeric; total numeric; fid uuid:=gen_random_uuid(); reg text; BEGIN SELECT * INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No company'; END IF; SELECT * INTO t FROM aircraft_types WHERE id=p_type AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown or inactive aircraft'; END IF; IF (SELECT count(*) FROM fleet_aircraft WHERE company_id=c.id)>=economy_number('max_active_leases') THEN RAISE EXCEPTION 'Lease limit reached'; END IF; bal:=company_balance(c.id); total:=t.security_deposit+t.weekly_rate; IF bal<total THEN RAISE EXCEPTION 'Insufficient Smooth Coins'; END IF; reg:='SS-'||c.icao_code||upper(substr(replace(fid::text,'-',''),1,6)); INSERT INTO fleet_aircraft(id,company_id,aircraft_type_id,registration,location_icao,lease_deposit,weekly_rate,next_payment_due) VALUES(fid,c.id,t.id,reg,c.home_base_icao,t.security_deposit,t.weekly_rate,now()+interval '7 days'); INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,'LEASE_DEPOSIT','LESSOR_DEPOSITS','COMPANY_CASH',t.security_deposit,-t.security_deposit,bal-t.security_deposit,'Security deposit – '||reg,reg,'lease_deposit:'||fid),(c.id,'LEASE_PAYMENT','LESSOR_REVENUE','COMPANY_CASH',t.weekly_rate,-t.weekly_rate,bal-total,'First weekly lease payment – '||reg,reg,'lease_payment:'||fid||':1'); RETURN fid; END $$;